import { validateNodes } from './validate-nodes.mjs';

function uniqueDeps(deps) {
  return [...new Set(deps)];
}

export function planBuild(nodes) {
  validateNodes(nodes);
  if (nodes.length === 0) return [];

  const inDegree = new Map(nodes.map((node) => [node.id, 0]));
  const dependents = new Map(nodes.map((node) => [node.id, []]));

  for (const node of nodes) {
    for (const dep of uniqueDeps(node.dependsOn === undefined ? [] : node.dependsOn)) {
      inDegree.set(node.id, inDegree.get(node.id) + 1);
      dependents.get(dep).push(node.id);
    }
  }

  const scheduled = new Set();
  const result = [];

  while (result.length < nodes.length) {
    let pick = null;
    for (const node of nodes) {
      if (scheduled.has(node.id)) continue;
      if (inDegree.get(node.id) === 0) {
        pick = node;
        break;
      }
    }
    if (!pick) throw new Error('cycle');
    scheduled.add(pick.id);
    result.push(pick.id);
    for (const child of dependents.get(pick.id)) {
      inDegree.set(child, inDegree.get(child) - 1);
    }
  }

  return result;
}

