function uniqueDeps(deps) {
  return [...new Set(deps)];
}

function assertCycleFree(nodes) {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const state = new Map(nodes.map((node) => [node.id, 0]));

  function visit(id) {
    const mark = state.get(id);
    if (mark === 2) return;
    if (mark === 1) throw new Error('cycle');
    state.set(id, 1);
    const node = byId.get(id);
    const deps = node.dependsOn === undefined ? [] : node.dependsOn;
    for (const dep of uniqueDeps(deps)) visit(dep);
    state.set(id, 2);
  }

  for (const node of nodes) {
    if (state.get(node.id) === 0) visit(node.id);
  }
}

export function validateNodes(nodes) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');

  const seenIds = new Set();
  const knownIds = new Set();

  for (const node of nodes) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('node must be an object');
    }
    if (typeof node.id !== 'string' || node.id.length === 0) {
      throw new TypeError('node id must be a nonempty string');
    }
    if (seenIds.has(node.id)) throw new Error('duplicate node id');
    seenIds.add(node.id);
    knownIds.add(node.id);

    if (node.dependsOn !== undefined) {
      if (!Array.isArray(node.dependsOn)) {
        throw new TypeError('dependsOn must be an array');
      }
      for (const dep of node.dependsOn) {
        if (typeof dep !== 'string' || dep.length === 0) {
          throw new TypeError('dependency id must be a nonempty string');
        }
      }
    }
  }

  for (const node of nodes) {
    const deps = node.dependsOn === undefined ? [] : node.dependsOn;
    for (const dep of uniqueDeps(deps)) {
      if (!knownIds.has(dep)) throw new Error('missing dependency');
    }
  }

  assertCycleFree(nodes);
  return nodes;
}

