import assert from 'node:assert/strict';
import { planBuild } from '../src/plan-build.mjs';
test('schedules a linear dependency chain',()=>{assert.deepEqual(planBuild([{id:'bundle',dependsOn:['compile']},{id:'compile',dependsOn:['parse']},{id:'parse'}]),['parse','compile','bundle']);});
